def numPrimeArrangements(n):
    MOD = 10**9 + 7

    # Sieve of Eratosthenes to find primes
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n + 1, i):
                is_prime[j] = False

    # Count primes
    prime_count = sum(is_prime[1:n+1])
    non_prime_count = n - prime_count

    # Calculate factorial of prime_count and non_prime_count
    def factorial(x):
        result = 1
        for i in range(1, x + 1):
            result = (result * i) % MOD
        return result

    return (factorial(prime_count) * factorial(non_prime_count)) % MOD

class Solution:
    def addBinary(self, a: str, b: str) -> str:
        carry = 0
        result = []
        i = len(a) - 1
        j = len(b) - 1

        while i >= 0 or j >= 0 or carry != 0:
            # Add the current digits from both strings to carry
            if i >= 0:
                carry += int(a[i])
                i -= 1
            if j >= 0:
                carry += int(b[j])
                j -= 1

            # Add the current bit to result and update carry
            result.append(str(carry % 2))
            carry //= 2

        # Reverse the result and join to form the final binary string
        return ''.join(reversed(result))

