class Solution:
    def PredictTheWinner(self, nums: List[int]) -> bool:
        n = len(nums)
        memo = {}

        def dp(left, right):
            if left > right:
                return 0
            if (left, right) in memo:
                return memo[(left, right)]

            # Current player can choose leftmost or rightmost element
            # The score difference is the chosen element minus the best score difference
            # the opponent can achieve in the remaining subarray
            choose_left = nums[left] - dp(left + 1, right)
            choose_right = nums[right] - dp(left, right - 1)

            memo[(left, right)] = max(choose_left, choose_right)
            return memo[(left, right)]

        # Return true if the maximum score difference is >= 0
        return dp(0, n - 1) >= 0

