def maximumSwap(num):
    digits = list(str(num))
    n = len(digits)

    # Find the rightmost occurrence of the maximum digit from the right
    max_digit_idx = n - 1
    swap_idx_left = -1
    swap_idx_right = -1

    # Traverse from right to left
    for i in range(n - 1, -1, -1):
        if digits[i] > digits[max_digit_idx]:
            max_digit_idx = i
        elif digits[i] < digits[max_digit_idx]:
            swap_idx_left = i
            swap_idx_right = max_digit_idx

    # If we found a valid swap, perform it
    if swap_idx_left != -1:
        digits[swap_idx_left], digits[swap_idx_right] = digits[swap_idx_right], digits[swap_idx_left]

    return int(''.join(digits))

