class Solution:
    def totalHammingDistance(self, nums: List[int]) -> int:
        total = 0
        n = len(nums)

        # Check each bit position from 0 to 31
        for bit in range(32):
            count_ones = 0
            # Count how many numbers have the current bit set
            for num in nums:
                if (num >> bit) & 1:
                    count_ones += 1

            # Count of numbers with current bit unset
            count_zeros = n - count_ones

            # Number of pairs with differing bits at this position
            total += count_ones * count_zeros

        return total

