class Solution:
    def myPow(self, x: float, n: int) -> float:
        # Handle negative exponent by converting to positive and taking reciprocal
        if n < 0:
            x = 1 / x
            n = -n

        # Base case
        if n == 0:
            return 1.0

        # Divide-and-conquer: compute pow(x, n//2) once
        half = self.myPow(x, n // 2)

        # If n is even: x^n = (x^(n/2))^2
        # If n is odd: x^n = (x^(n/2))^2 * x
        if n % 2 == 0:
            return half * half
        else:
            return half * half * x

class Solution:
    def numberOfBoomerangs(self, points: List[List[int]]) -> int:
        ans = 0
        for i in range(len(points)):
            m = {}
            # Count frequency of squared distances from point i to all other points
            for j in range(len(points)):
                if i != j:
                    dx = points[i][0] - points[j][0]
                    dy = points[i][1] - points[j][1]
                    d = dx * dx + dy * dy
                    m[d] = m.get(d, 0) + 1

            # For each distance, if d points are at that distance, 
            # we can form d * (d - 1) boomerangs (ordered pairs)
            for count in m.values():
                if count >= 2:
                    ans += count * (count - 1)

        return ans

