    return [i for i in range(2, n + 1) if is_prime[i]]

def prime_factorization(n, primes):
    factors = []
    for p in primes:
        if p * p > n:
            break
        while n % p == 0:
            factors.append(p)
            n //= p
    if n > 1:
        factors.append(n)
    return factors

def canTraverseAllPairs(nums):
    n = len(nums)
    if n == 1:
        return True

    if 1 in nums:
        return False

    # Check if all elements are the same
    if all(x == nums[0] for x in nums):
        return True

    # Find maximum value to generate primes
    max_val = max(nums)
    primes = sieve_of_eratosthenes(max_val)

    uf = UnionFind(n)
    prime_to_index = {}

    for i, num in enumerate(nums):
        factors = prime_factorization(num, primes)
        for p in factors:
            if p in prime_to_index:
                uf.union(i, prime_to_index[p])
            else:
                prime_to_index[p] = i

    # Check if all indices are connected
    root = uf.find(0)
    for i in range(1, n):
        if uf.find(i) != root:
            return False

    return True

