class Solution:
    def replaceNonCoprimes(self, nums: List[int]) -> List[int]:
        def lcm(a, b):
            return a * b // gcd(a, b)

        stack = []

        for num in nums:
            # Keep combining with the top of stack while they are non-coprime
            while stack and gcd(stack[-1], num) > 1:
                top = stack.pop()
                num = lcm(top, num)
            stack.append(num)

        return stack

