def reachingPoints(sx, sy, tx, ty):
    while tx >= sx and ty >= sy:
        if tx == ty:
            break
        if tx > ty:
            if ty == sy:
                return (tx - sx) % ty == 0
            tx %= ty
        else:
            if tx == sx:
                return (ty - sy) % tx == 0
            ty %= tx

    return tx == sx and ty == sy

class Solution:
    def calculate(self, s: str) -> int:
        def helper(s, start):
            stack = []
            num = 0
            sign = '+'

            i = start
            while i < len(s):
                char = s[i]
                if char.isdigit():
                    num = num * 10 + int(char)
                elif char == '(':
                    # Recursively evaluate the expression inside parentheses
                    num, new_i = helper(s, i + 1)
                    i = new_i
                elif char in '+-*/)' or i == len(s) - 1:
                    # Process the previous number with the current sign
                    if i == len(s) - 1 or char == ')':
                        # Handle the last number in the expression
                        if sign == '+':
                            stack.append(num)
                        elif sign == '-':
                            stack.append(-num)
                        elif sign == '*':
                            stack.append(stack.pop() * num)
                        elif sign == '/':
                            top = stack.pop()
                            if top < 0:
                                stack.append(-(-top // num))
                            else:
                                stack.append(top // num)

                        # If we're at the end or at a closing parenthesis, return
                        if char == ')':
                            return sum(stack), i + 1
                        else:
                            # We've processed the last number, so we can return
                            return sum(stack), i + 1
                    else:
                        # Process the previous number with the current sign
                        if sign == '+':
                            stack.append(num)
                        elif sign == '-':
                            stack.append(-num)
                        elif sign == '*':
                            stack.append(stack.pop() * num)
                        elif sign == '/':
                            top = stack.pop()
                            if top < 0:
                                stack.append(-(-top // num))
                            else:
                                stack.append(top // num)

                        # Reset num and update sign
                        num = 0
                        sign = char

                i += 1

            return sum(stack), i

        result, _ = helper(s, 0)
        return result

def countDigitOne(n):
    if n == 0:
        return 0

    count = 0
    position = 1

    while position <= n:
        higher = n // (position * 10)
        current = (n // position) % 10
        lower = n % position

        if current == 0:
            count += higher * position
        elif current == 1:
            count += higher * position + lower + 1
        else:
            count += (higher + 1) * position

        position *= 10

    return count

def countAnagrams(s: str) -> int:
    MOD = 10**9 + 7

    def mod_inverse(a, mod):
        return pow(a, mod - 2, mod)

    def factorial(n):
        result = 1
        for i in range(1, n + 1):
            result = (result * i) % MOD
        return result

    words = s.split()
    ways = 1

    for word in words:
        n = len(word)
        freq = {}
        for char in word:
            freq[char] = freq.get(char, 0) + 1

        # Calculate n! / (f1! * f2! * ... * fk!)
        numerator = factorial(n)
        denominator = 1
        for count in freq.values():
            denominator = (denominator * factorial(count)) % MOD

        # Multiply by modular inverse of denominator
        word_ways = (numerator * mod_inverse(denominator, MOD)) % MOD
        ways = (ways * word_ways) % MOD

    return ways

class Solution:
    def xorGame(self, nums: List[int]) -> bool:
        xor_sum = 0
        for num in nums:
            xor_sum ^= num

        # If initial XOR is 0, Alice wins immediately
        if xor_sum == 0:
            return True

        # If initial XOR is not 0, Alice wins if number of elements is odd
        # Alice loses if number of elements is even
        return len(nums) % 2 == 1

class Solution:
    def maxValueAfterReverse(self, nums: List[int]) -> int:
        n = len(nums)
        total = 0
        for i in range(n - 1):
            total += abs(nums[i] - nums[i + 1])

        max_improvement = 0

        # Try all possible subarray reversals
        for i in range(n):
            for j in range(i + 1, n):
                # Calculate the improvement from reversing subarray from i to j
                improvement = 0

                # If there's a left boundary (i > 0), calculate change at position i-1
                if i > 0:
                    improvement += abs(nums[i - 1] - nums[j]) - abs(nums[i - 1] - nums[i])

                # If there's a right boundary (j < n-1), calculate change at position j
                if j < n - 1:
                    improvement += abs(nums[i] - nums[j - 1]) - abs(nums[j - 1] - nums[j])

                max_improvement = max(max_improvement, improvement)

        return total + max_improvement

def kMirror(k, n):
    def is_palindrome(s):
        return s == s[::-1]

    def to_base(num, base):
        if num == 0:
            return "0"
        digits = []
        while num:
            digits.append(str(num % base))
            num //= base
        return ''.join(reversed(digits))

    count = 0
    total_sum = 0
    num = 1

    while count < n:
        # Check if the number is palindrome in base-10
        if is_palindrome(str(num)):
            # Convert to base-k and check if it's palindrome
            base_k = to_base(num, k)
            if is_palindrome(base_k):
                total_sum += num
                count += 1
        num += 1

    return total_sum
